const display=v=>Number((unit==='mm'?v:v/25.4).toFixed(unit==='mm'?3:5));
const from=v=>Number(v)*(unit==='mm'?1:25.4), snapshot=()=>JSON.stringify(p);
function toast(t){$('#toast').textContent=t;$('#toast').style.opacity=1;clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.opacity=0,3500)}
function remember(){ArtworkUI.flush();history.push(snapshot());if(history.length>60)history.shift();future=[];updateHistory()}
function updateHistory(){$('#undo').disabled=!history.length;$('#redo').disabled=!future.length}
function store(key,data){try{localStorage.setItem(key,JSON.stringify(data));return true}catch{toast('Browser storage unavailable. Export your settings as JSON.');return false}}
function download(content,name,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function pathD(points,close=false){return 'M'+points.map(a=>a.map(G.round).join(' ')).join('L')+(close?'Z':'')}
function paths(g,thumbnail=false){return `<path d="${pathD(g.cut,true)}" fill="${colors[p.stock]}" stroke="#c67b58" stroke-width="${thumbnail?1:.6}" stroke-linejoin="round"/>${g.circles.map(c=>`<circle cx="${c.x}" cy="${c.y}" r="${c.r}" fill="#f8f9f5" stroke="#c67b58" stroke-width=".6"/>`).join('')}${g.fold.map(points=>`<path d="${pathD(points)}" fill="none" stroke="#7a8f77" stroke-width=".5" stroke-dasharray="3 2"/>`).join('')}`}
