function renderLibrary(){let list=templates.filter(t=>(category==='All'||t.category===category)&&t.name.toLowerCase().includes($('#search').value.toLowerCase()));if($('#sort').value==='name')list.sort((a,b)=>a.name.localeCompare(b.name));$('#categories').innerHTML=['All','Envelopes','Boxes','Bags','More'].map(c=>`<button class="${c===category?'selected':''}" data-category="${c}">${c}</button>`).join('');$('#resultCount').textContent=list.length+' templates';$('#templates').innerHTML=list.map(t=>{const g=G.generate(t,G.defaults(t));return `<button class="template ${selected.id===t.id?'selected':''}" data-id="${t.id}" aria-label="Select ${t.name}" aria-pressed="${selected.id===t.id}"><div class="thumb"><svg viewBox="-8 -8 ${g.bw+16} ${g.bh+16}">${paths(g,true)}</svg></div><strong>${t.name}</strong><small>${t.tag}</small></button>`}).join('')||'<div class="empty">No templates found. Try another name or category.</div>';document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>{remember();choose(b.dataset.id)});document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;renderLibrary()})}
function numericField(key,label,min,max){return `<label class="field">${label}<div><input data-param="${key}" id="${key}" type="number" min="${display(min)}" max="${display(max)}" step="any" value="${display(p[key])}" aria-label="${label}" inputmode="decimal"><span class="unit-label">${unit}</span></div></label>`}
function renderFields(){const f=G.fields(selected.kind);$('#fields').innerHTML=f.main.map(a=>numericField(...a)).join('');$('#advancedFields').innerHTML=f.extra.map(a=>numericField(...a)).join('');$('#stockFields').innerHTML=numericField('thickness','Stock thickness',.01,10);$('#lockRatio').checked=p.lock;$('#stock').value=p.stock;$('#paper').value=p.paper;$('#paperFields').innerHTML=numericField('paperW','Sheet width',1,20000)+numericField('paperH','Sheet height',1,20000)+numericField('margin','Sheet margin',0,1000);$('#paperFields').querySelectorAll('.field').forEach((e,i)=>e.hidden=p.paper!=='custom'&&i<2);$('#presetEnvelope').hidden=selected.kind!=='envelope';
  document.querySelectorAll('[data-param]').forEach(input=>{
    input.addEventListener('wheel',event=>event.preventDefault(),{passive:false});
    input.onfocus=()=>{input.dataset.before=snapshot()};
    input.oninput=()=>{
      const key=input.dataset.param,value=input.value===''?NaN:from(input.value),old=p[key];
      p[key]=value;
      if(p.lock&&['w','h'].includes(key)&&Number.isFinite(value)&&value>0&&Number.isFinite(old)&&old>0){const other=key==='w'?'h':'w';p[other]=G.round(p[other]*value/old);$('#'+other).value=Number.isFinite(p[other])?display(p[other]):''}
      renderDrawing();
    };
    input.onchange=()=>{const before=input.dataset.before;if(before&&before!==snapshot()){history.push(before);history=history.slice(-60);future=[];updateHistory()}input.dataset.before=snapshot()};
  });
  renderPresets();
}
function syncTitle(){$('#title').textContent=selected.name;$('#crumb').textContent=selected.category;$('#templateId').textContent=selected.id;$('#canvasName').textContent=selected.name.toUpperCase();$('#description').textContent='Set every fold to fit your idea. All dimensions update live.';$('#save').textContent='♡'}
function choose(id,state){selected=templates.find(t=>t.id===id)||templates[0];p=state||G.defaults(selected);syncTitle();renderFields();renderLibrary();renderDrawing();updateHistory()}
function dimensionLines(g){
  const f=g.face,s=10*CanvasStudio.unitSize(),offset=s*.8;
  const label=(x,y,text)=>`<text x="${x}" y="${y}" font-size="${s}" fill="#687f62" stroke="${colors[p.stock]}" stroke-width="${s*.55}" paint-order="stroke" text-anchor="middle">${text}</text>`;
  return `<g fill="none" stroke="#8c9c88" stroke-width=".5"><path d="M${f.x} ${f.y+f.h*.5}h${f.w}m0 -3v6m${-f.w} -6v6"/><path d="M${f.x+f.w*.7} ${f.y}v${f.h}m-3 0h6m-6 ${-f.h}h6"/></g><g font-family="DM Sans,sans-serif">${label(f.x+f.w/2,f.y+f.h*.5-offset,`${display(f.w)} ${unit}`)}${label(f.x+f.w*.7,f.y+f.h*.8,`${display(f.h)} ${unit}`)}${selected.kind==='envelope'?label(f.x+f.w/2,f.y/2,`Top ${display(p.top)} ${unit}`):''}</g>`;
}
function renderDrawing(){errors=G.validate(selected,p);document.querySelectorAll('[data-param]').forEach(el=>{const error=errors.find(e=>e.key===el.dataset.param);el.setCustomValidity(error?error.message:'');el.setAttribute('aria-invalid',String(Boolean(error)))});$('#validation').hidden=!errors.length;$('#validation').textContent=errors.length?errors.map(e=>e.message).join(' '):'';$('#download').disabled=!!errors.length;$('#print').disabled=!!errors.length;$('#save').disabled=!!errors.length;$('#savePreset').disabled=!!errors.length;$('#exportSettings').disabled=!!errors.length;$('#staleDrawing').hidden=!errors.length;
  if(errors.length){$('#sheetSize').textContent='Invalid dimensions';$('#paperStatus').textContent='Fix the marked values before exporting.';return}
  geometry=G.generate(selected,p);const g=geometry;fit=G.sheetFit(g,p);if(p.layout?.enabled){const check=FoldLayout.check(p.layout,g,p);fit={sheetW:p.paperW,sheetH:p.paperH,rotate:false,fits:check.fits,layout:check}}ArtworkUI.sync();LayoutUI.sync();
  CanvasStudio.render(g,p,fit,selected);$('#sheetSize').textContent=`${display(g.bw)} × ${display(g.bh)} ${unit}`;$('#sheetTotal').textContent=`${display(fit.sheetW)} × ${display(fit.sheetH)} ${unit}`;$('#bodySize').textContent=`${display(g.body.w)} × ${display(g.body.h)}${['box','bag','tray'].includes(selected.kind)?' × '+display(g.body.d):''} ${unit}`;$('#paperStatus').textContent=fit.fits?(fit.rotate?'Fits rotated 90° · print at actual size':'Fits at actual size · includes sheet margins'):'Dieline exceeds the usable sheet area';$('#paperStatus').classList.toggle('warning',!fit.fits);$('#canvasUnit').textContent=unit==='mm'?'millimeters':'inches';document.documentElement.style.setProperty('--paper',colors[p.stock]);$('#previewObject').style.width=Math.min(250,250*g.body.w/g.body.h)+'px';$('#previewObject').style.height='250px';$('#previewObject').classList.toggle('box',selected.kind!=='envelope');updatePrintStyles();
  if(p.layout?.enabled){$('#paperStatus').textContent=fit.fits?`${p.layout.items.length} copies · actual size`:`${fit.layout.outside.length} outside · ${fit.layout.pairs.length} overlapping / too close`}
}
function updatePrintStyles(){if(!geometry)return;let style=$('#printPageStyle');if(!style){style=document.createElement('style');style.id='printPageStyle';document.head.append(style)}style.textContent=`@media print{@page{size:${fit.sheetW}mm ${fit.sheetH}mm;margin:0}.canvas #drawing{width:${fit.sheetW}mm!important;height:${fit.sheetH}mm!important;position:absolute!important;left:0!important;top:0!important;transform:none!important;}}`}
function setZoom(v){CanvasStudio.setZoom(v);$('#previewObject').style.transform=`rotate(-8deg) scale(${zoom})`}
function setMode(m){mode=m;$('#flat').classList.toggle('selected',m==='flat');$('#folded').classList.toggle('selected',m==='folded');$('#drawing').style.display=m==='flat'?'block':'none';$('#previewObject').hidden=m==='flat';if(m==='folded')toast('Appearance preview only. Prototype the exported dieline for fit.')}
function openModal(html){$('#modalContent').innerHTML=html;$('#modal').showModal()}
function applyState(state){const t=templates.find(t=>t.id===state.template);if(!t)throw new Error('Unknown template');const base=G.defaults(t),next={...base};for(const key of Object.keys(base))if(Object.hasOwn(state,key))next[key]=state[key];if(!Object.hasOwn(colors,next.stock))throw new Error('Unknown paper stock');if(!['auto','a4','a3','letter','custom'].includes(next.paper))throw new Error('Unknown paper size');if(typeof next.lock!=='boolean')throw new Error('Invalid aspect lock');next.artwork=FoldArtwork.normalize(next.artwork);next.layout=FoldLayout.normalize(next.layout);if(next.layout.enabled&&next.paper==='auto')throw new Error('Sheet layout requires a fixed paper size.');const invalid=G.validate(t,next);if(invalid.length)throw new Error(invalid[0].message);remember();choose(t.id,next)}
function restore(historySource,historyTarget){if(!historySource.length)return;historyTarget.push(snapshot());const state=JSON.parse(historySource.pop());choose(state.template,state)}
function renderPresets(){$('#customPresets').innerHTML='<option value="">Your saved sizes…</option>'+sizePresets.filter(v=>v.state?.template===selected.id).map(v=>`<option value="${escapeHtml(v.id)}">${escapeHtml(v.name)}</option>`).join('')}
function migrateDesign(v){const t=templates.find(t=>t.id===(v.state?.template||v.template));if(!t)throw new Error('Template is unavailable');if(v.state)return v.state;return {...G.defaults(t),w:v.w,h:v.h,d:v.d||40,top:v.flap||40,thickness:v.thickness||.3,stock:v.stock||'ivory'}}
$('#search').oninput=renderLibrary;$('#sort').onchange=renderLibrary;$('#flat').onclick=()=>setMode('flat');$('#folded').onclick=()=>setMode('folded');$('#plus').onclick=()=>setZoom(zoom+.1);$('#minus').onclick=()=>setZoom(zoom-.1);$('#fit').onclick=()=>{CanvasStudio.fitView();zoom=1;$('#previewObject').style.transform='rotate(-8deg)'};$('#showDimensions').onchange=renderDrawing;
$('#stock').onchange=e=>{remember();p.stock=e.target.value;renderDrawing();renderLibrary()};
$('#paper').onchange=e=>{remember();p.paper=e.target.value;if(p.paper==='auto'&&p.layout?.enabled)p.layout={...p.layout,enabled:false};const sizes={a4:[210,297],a3:[297,420],letter:[215.9,279.4]};if(sizes[p.paper])[p.paperW,p.paperH]=sizes[p.paper];renderFields();renderDrawing()};
document.querySelectorAll('[data-unit]').forEach(b=>b.onclick=()=>{unit=b.dataset.unit;document.querySelectorAll('[data-unit]').forEach(x=>x.classList.toggle('selected',x===b));renderFields();renderDrawing()});
