$('#lockRatio').onchange=e=>{remember();p.lock=e.target.checked;toast(p.lock?'Width / height ratio locked':'Width / height can change independently')};
$('#swapSize').onclick=()=>{remember();[p.w,p.h]=[p.h,p.w];renderFields();renderDrawing()};
$('#resetSize').onclick=()=>{remember();choose(selected.id,{...G.defaults(selected),artwork:p.artwork});toast('Template dimensions reset · background images retained')};
$('#undo').onclick=()=>{ArtworkUI.flush();restore(history,future)};$('#redo').onclick=()=>{ArtworkUI.flush();restore(future,history)};
$('#applyScale').onclick=()=>{const factor=Number($('#scalePercent').value)/100;if(!Number.isFinite(factor)||factor<=0||factor>100){toast('Enter a scale greater than 0 and up to 10,000%.');return}const next={...p};for(const [key]of [...G.fields(selected.kind).main,...G.fields(selected.kind).extra])next[key]=G.round(next[key]*factor);try{applyState(next);toast('Dieline dimensions scaled. Stock thickness and paper size retained.')}catch(e){toast(e.message)}};
$('#savePreset').onclick=()=>{if(errors.length)return;openModal('<h2 class="modal-title">Save a custom size</h2><p class="muted">Keeps all dimensions, flaps, stock, and page settings for this template.</p><label class="field">Size name<input id="presetName" maxlength="80" placeholder="e.g. Wedding invitation · 120 × 180"></label><button class="modal-primary" id="confirmPreset">Save size</button>');$('#presetName').focus();$('#confirmPreset').onclick=()=>{const name=$('#presetName').value.trim();if(!name){$('#presetName').focus();return}const entry={id:String(Date.now()),name,state:{...p}};if(store('fold-size-presets',[...sizePresets,entry])){sizePresets.push(entry);renderPresets();$('#modal').close();toast('Custom size saved locally')}}};
$('#customPresets').onchange=e=>{const v=sizePresets.find(v=>v.id===e.target.value);if(v)try{applyState(v.state);$('#customPresets').value=v.id}catch(err){toast(err.message)}};
$('#exportSettings').onclick=()=>{if(errors.length)return;try{const assets=FoldArtwork.bundle(p.artwork);download(JSON.stringify({format:'fold-design',version:1,name:selected.name,state:p,assets},null,2),'fold-'+selected.name.toLowerCase().replaceAll(' ','-')+'-settings.json','application/json');toast('Editable settings and images exported')}catch(error){toast(error.message)}};
$('#importSettings').onclick=()=>$('#settingsFile').click();$('#settingsFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>30000000)throw new Error('Settings file must be smaller than 30 MB including images.');const data=JSON.parse(await file.text());if(data.format!=='fold-design'||data.version!==1||!data.state)throw new Error('Choose a Fold settings JSON file (version 1).');const assets=FoldArtwork.validateAssets(data.assets||[]),art=FoldArtwork.normalize(data.state.artwork),known=new Set([...FoldArtwork.cache.keys(),...assets.map(a=>a.id)]);if(FoldArtwork.assetIds(art).some(id=>!known.has(id)))throw new Error('This settings file is missing an embedded image. Export a fresh backup from the original browser.');const stored=assets.length?await FoldArtwork.saveAssets(assets):true;applyState(data.state);toast(stored?'Settings and images imported':'Imported for this session. Export JSON to keep a backup.')}catch(err){toast('Import failed: '+err.message)}e.target.value=''};
$('#save').onclick=()=>{if(errors.length)return;const v={id:Date.now(),name:selected.name,state:{...p}};if(store('fold-designs',[...designs,v])){designs.push(v);$('#savedCount').textContent=designs.length;$('#save').textContent='♥';toast('Design saved in this browser')}};
$('#projects').onclick=()=>{openModal('<h2 class="modal-title">My designs</h2><p class="muted">Saved locally in this browser, including every custom dimension.</p>'+(designs.length?designs.map(v=>`<button class="saved-item" data-saved="${escapeHtml(v.id)}"><b>${escapeHtml(v.name)}</b><span>${escapeHtml(v.state?`${v.state.w} × ${v.state.h}`:`${v.w} × ${v.h}`)} mm ↗</span></button>`).join(''):'<p class="instruction">Use the heart beside a template to save your first design.</p>'));document.querySelectorAll('[data-saved]').forEach(b=>b.onclick=()=>{try{const v=designs.find(x=>String(x.id)===b.dataset.saved);applyState(migrateDesign(v));$('#modal').close()}catch(err){toast(err.message)}})};
$('#browse').onclick=()=>{$('#search').value='';category='All';renderLibrary();$('.library').scrollIntoView({behavior:'smooth'})};$('.close').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal'))$('#modal').close()};
$('#instructions').onclick=()=>openModal(`<h2 class="modal-title">Fold your ${selected.name.toLowerCase()}</h2><ol class="instruction"><li>Print at <b>100% / actual size</b>. Verify a measured edge first.</li><li>Cut along the orange outline${selected.kind==='tag'?' and punch the hole':''}.</li><li>Score the dashed green folds before assembly.</li><li>${selected.kind==='envelope'?'Fold side tabs inward, glue the side edges of the bottom flap, then fold it upward. Keep the pocket opening clear.':selected.kind==='tray'?'Raise the four walls. This open tray has no glue tabs; tape the corners for a prototype.':selected.kind==='tag'?'Thread a ribbon through the hole and attach to your gift.':'Form the side seam at the glue tab. Fold the base and closure panels; use paper glue where needed.'}</li><li>Make a paper prototype. Stock thickness is recorded but does not automatically compensate the geometry.</li></ol>`);
$('#guide').onclick=()=>openModal('<h2 class="modal-title">Make every fold your own.</h2><ol class="instruction"><li>Enter width, height, and depth where applicable. Dimensions support 1–5,000 mm and decimal input.</li><li>Use aspect lock, swap width/height, or scale the whole dieline.</li><li>Open Fold geometry to customize flaps, glue tabs, chamfers, closure curves, or tag holes.</li><li>Content clearance adds space to both sides of the body. The actual panel size is shown in the summary.</li><li>Choose a custom sheet and margins to check fit. Exported SVG/DXF uses millimeters at true size.</li><li>Save a named custom size or export/import editable JSON settings. Everything stays local.</li></ol><p class="muted">Thickness is recorded, not compensated. Folded preview is illustrative. Test a prototype before production.</p>');
function sheetItems(){return p.layout?.enabled?p.layout.items:[{id:'single',x:p.margin,y:p.margin,rotation:fit.rotate?90:0}]}
function sheetMarkup(){return `<defs><g id="export-master">${artworkDieline(geometry,true)}</g></defs>${sheetItems().map(item=>`<g data-sheet-copy="${item.id}" transform="${FoldLayout.transform(item,geometry)}"><use href="#export-master"/></g>`).join('')}`}
function exportSvg(){return `<svg xmlns="http://www.w3.org/2000/svg" width="${fit.sheetW}mm" height="${fit.sheetH}mm" viewBox="0 0 ${fit.sheetW} ${fit.sheetH}"><title>${escapeHtml(selected.name)} — ${G.round(p.w)} × ${G.round(p.h)} mm — ${sheetItems().length} copies</title><desc>Cut: orange. Crease: dashed green. True-size millimeters. Stock thickness recorded, not compensated. Prototype before production.</desc><metadata>${escapeHtml(JSON.stringify({format:'fold-design',version:1,state:p}))}</metadata>${sheetMarkup()}</svg>`}
function exportDxf(){const g=geometry,out=['0','SECTION','2','HEADER','9','$INSUNITS','70','4','0','ENDSEC','0','SECTION','2','ENTITIES'];for(const item of sheetItems()){const pt=a=>FoldLayout.point(item,g,a),line=(a,b,layer)=>{if(a[0]===b[0]&&a[1]===b[1])return;const A=pt(a),B=pt(b);out.push('0','LINE','8',layer,'10',String(A[0]),'20',String(G.round(fit.sheetH-A[1])),'30','0','11',String(B[0]),'21',String(G.round(fit.sheetH-B[1])),'31','0')};g.cut.forEach((a,i)=>line(a,g.cut[(i+1)%g.cut.length],'CUT'));g.fold.forEach(points=>points.slice(1).forEach((b,i)=>line(points[i],b,'CREASE')));g.circles.forEach(c=>{const a=pt([c.x,c.y]);out.push('0','CIRCLE','8','CUT','10',String(a[0]),'20',String(G.round(fit.sheetH-a[1])),'30','0','40',String(c.r))})}out.push('0','ENDSEC','0','EOF');return out.join('\n')}
$('#download').onclick=()=>{if(errors.length)return;if(!fit.fits){toast(p.layout?.enabled?'Copies overlap or exceed the margins. Rearrange before exporting.':'Choose a larger sheet or Auto before exporting.');$(p.layout?.enabled?'#sheetLayoutPanel':'#pageSetup').open=true;$(p.layout?.enabled?'#sheetLayoutPanel':'#pageSetup').scrollIntoView({behavior:'smooth',block:'center'});return}const format=$('#format').value.toLowerCase();download(format==='svg'?exportSvg():exportDxf(),`fold-${selected.name.toLowerCase().replaceAll(' ','-')}-${G.round(p.w)}x${G.round(p.h)}mm${p.layout?.enabled?'-'+p.layout.items.length+'up':''}.${format}`,format==='svg'?'image/svg+xml':'application/dxf');toast(`${format.toUpperCase()} exported · ${sheetItems().length} copies at actual size`)};
